#!/usr/bin/env bash

# Synopsis:
# Test the test runner by running it against a predefined set of solutions
# with an expected output.

# Output:
# Outputs the diff of the expected test results against the actual test results
# generated by the test runner.

# Example:
# ./bin/run-tests.sh

exit_code=0

for test_dir in tests/*; do
    test_dir_name=$(basename "${test_dir}")
    test_dir_path=$(realpath "${test_dir}")
    actual_results="${test_dir_path}/results.json"
    expected_results="${test_dir_path}/expected_results.json"

    bin/run.sh "${test_dir_name}" "${test_dir_path}" "${test_dir_path}"

    # Uncomment to update the `expected_results.json` files.
    # cp "${actual_results}" "${expected_results}"
    if [[ -e "${actual_results}" ]]; then
        echo "${test_dir_name}: comparing results.json to expected_results.json"
        if ! diff "${actual_results}" "${expected_results}"; then
            exit_code=1
        fi
        rm "${actual_results}"
    else
        exit_code=1
        echo "${test_dir_name}: results.json is missing!!"
    fi
done

exit "${exit_code}"
